package com.nyayaconnect.ai;
import com.nyayaconnect.common.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;
public class DocumentSummaryServlet extends HttpServlet{protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{try{Map<?,?> b=Json.MAPPER.readValue(req.getInputStream(),Map.class);String name=get(b,"docName","Legal document");String type=get(b,"docType","Unknown");String content=get(b,"content");String clipped=content.length()>4000?content.substring(0,4000):content;Api.json(res,200,Map.of("docClassification",type,"partiesIdentified",List.of(),"effectiveDate","Not reliably extracted","monetaryValue","Not reliably extracted","keyClauses",List.of(),"plainLanguageSummary","No authoritative AI extraction is configured in this deployment. The document should be reviewed by a lawyer before reliance.","potentialRiskPoints",List.of("Do not rely on automated extraction as legal advice.","Original document integrity should be preserved.","AI processing must be enabled with approved data-handling controls."),"inputCharacters",clipped.length(),"documentName",name));}catch(Exception e){Api.error(res,400,"INVALID_REQUEST","Invalid document summary request.");}}
 private static String get(Map<?,?> m,String k){return get(m,k,"");}
 private static String get(Map<?,?> m,String k,String d){Object v=m.get(k);return v==null?d:String.valueOf(v);}
}
